ST.xhtml:
model.actualStatus := THIS^.actualStatus;
model.powerFan := THIS^.powerFan;
model.stat := THIS^.stat;

model.limitSwitch1 := THIS^.limitSwitch1;
model.limitSwitch2 := THIS^.limitSwitch2;
model.limitSwitch3 := THIS^.limitSwitch3;
model.homeSensor1 := THIS^.homeSensor1;
model.homeSensor2 := THIS^.homeSensor2;
model.actualStatus := THIS^.actualStatus;
model.powerMount := THIS^.powerMount;
model.stat := THIS^.stat;
THIS^.proc.power_on._copyToModel_Process( model := model.proc.power_on );
THIS^.proc.power_off._copyToModel_Process( model := model.proc.power_off );

THIS^.proc.reset._copyFromModel_Process( model := model.proc.reset );
THIS^.proc.power_on._copyFromModel_Process( model := model.proc.power_on );
THIS^.proc.power_off._copyFromModel_Process( model := model.proc.power_off );

model.actualStatus := THIS^.actualStatus;
model.powerPC := THIS^.powerPC;
model.stat := THIS^.stat;
THIS^.proc.reset._copyToModel_Process( model := model.proc.reset );
THIS^.proc.power_on._copyToModel_Process( model := model.proc.power_on );
THIS^.proc.power_off._copyToModel_Process( model := model.proc.power_off );

parts.Fan();
parts.Mount();
parts.PC();
stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := ((parts.Mount.stat.health = HealthStatus.good) OR (parts.Mount.stat.health = HealthStatus.warning)) AND ((parts.Fan.stat.health = HealthStatus.good) OR (parts.Fan.stat.health = HealthStatus.warning)),
    hasWarning := (parts.Mount.stat.health = HealthStatus.warning) OR (parts.Fan.stat.health = HealthStatus.warning));
stat.enabled := F_EnabledStatus(
    superState := TRUE,
    isEnabled := parts.Mount.stat.enabled AND parts.PC.stat.enabled);
proc.power_on( isEnabled := (parts.Mount.stat.enabled = EnabledStatus.enabled) AND (parts.PC.stat.enabled = EnabledStatus.enabled) );
proc.power_off();
proc.reset();

THIS^.parts.Fan._copyFromModel_Ventilation( model := model.parts.Fan );
THIS^.parts.Mount._copyFromModel_SolarMount( model := model.parts.Mount );
THIS^.parts.PC._copyFromModel_SolarPC( model := model.parts.PC );
THIS^.proc.power_on._copyFromModel_Process( model := model.proc.power_on );
THIS^.proc.power_off._copyFromModel_Process( model := model.proc.power_off );
THIS^.proc.reset._copyFromModel_Process( model := model.proc.reset );

model.temp := THIS^.temp;
model.tempHealth := THIS^.tempHealth;
model.actualStatus := THIS^.actualStatus;
model.stat := THIS^.stat;
THIS^.parts.Fan._copyToModel_Ventilation( model := model.parts.Fan );
THIS^.parts.Mount._copyToModel_SolarMount( model := model.parts.Mount );
THIS^.parts.PC._copyToModel_SolarPC( model := model.parts.PC );
THIS^.proc.power_on._copyToModel_Process( model := model.proc.power_on );
THIS^.proc.power_off._copyToModel_Process( model := model.proc.power_off );
THIS^.proc.reset._copyToModel_Process( model := model.proc.reset );
